<script lang="ts">
 import {onMount} from 'svelte';import RecordTable from '$lib/components/RecordTable.svelte';import {Api} from '$lib/api';
 let fingerprints=$state<any[]>([]);let error=$state('');let busy=$state('');
 async function load(){try{fingerprints=await Api.signalFingerprints();error=''}catch(e){error=String(e)}}onMount(load);
 async function run(kind:'segment'|'extract'){busy=kind;try{if(kind==='segment')await Api.signalSegmentBursts();else await Api.signalPolyphaseExtract();await load()}catch(e){error=String(e)}finally{busy=''}}
</script>
<div class="page"><h1>Signal Identification</h1><p class="muted">Fingerprint captured signals and extract channelized bursts.</p>{#if error}<p class="error">{error}</p>{/if}<section class="card controls"><b>{fingerprints.length} fingerprints</b><button class="primary" onclick={()=>run('segment')} disabled={!!busy}>{busy==='segment'?'Working…':'Segment bursts'}</button><button onclick={()=>run('extract')} disabled={!!busy}>{busy==='extract'?'Working…':'Polyphase extract'}</button><button onclick={load}>Refresh</button></section><section class="card"><RecordTable rows={fingerprints} caption="Signal fingerprints" empty="No fingerprints exist. Capture a signal, then run Segment bursts." /></section></div>
<style>.page{padding:16px;overflow-y:auto;height:100%}.muted,small,.empty{color:var(--fg-dim)}.error{color:var(--danger)}.card{margin:12px 0;padding:14px;background:var(--bg-elev);border:1px solid var(--line);border-radius:8px}.controls{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.controls b{margin-right:auto}button{background:var(--bg);color:var(--fg);border:1px solid var(--line);padding:7px 11px;border-radius:5px}.primary{color:var(--accent);border-color:var(--accent)}.row{display:flex;gap:16px;border-top:1px solid var(--line);padding:8px 0;font:12px var(--mono);flex-wrap:wrap}.row span{min-width:120px;word-break:break-word}.row small{display:block;font:10px var(--sans)}.empty{text-align:center;padding:20px}</style>
